import threading
la, lb = threading.Lock(), threading.Lock()
def worker(order):
    for lk in order:
        lk.acquire()
    try:
        pass  # 临界区
    finally:
        for lk in reversed(order):
            lk.release()
# 所有线程按同一顺序 (la, lb) 获取锁，即可避免循环等待导致死锁
threading.Thread(target=worker, args=((la, lb),)).start()
threading.Thread(target=worker, args=((la, lb),)).start()
